export function aanmeldenBezig(nu=Date.now()):boolean{try{const t=Number(sessionStorage.getItem(AANMELD_BEZIG_SLEUTEL)||0);return t>0&&nu-t>=0&&nu-t<AANMELD_BEZIG_MS}catch{return false}}
